package com.bank.java11;

import java.io.IOException;
import java.nio.file.*;
import java.util.Optional;
import java.util.stream.Collectors;

public class StringFileDemo {

    public static void demonstrateStringMethods() {
        // ═══ isBlank() vs isEmpty() ═══
        "".isEmpty();           // true
        "".isBlank();           // true
        "   ".isEmpty();        // FALSE — has 3 chars
        "   ".isBlank();        // TRUE — all whitespace

        // ═══ strip() vs trim() — Unicode awareness ═══
        String unicodeSpace = "\u00A0RELIANCE\u00A0";  // non-breaking space
        unicodeSpace.trim();    // "\u00A0RELIANCE\u00A0" — trim() MISSES \u00A0!
        unicodeSpace.strip();   // "RELIANCE" — strip() handles Unicode whitespace!

        // Also: stripLeading() and stripTrailing()
        " RELIANCE ".stripLeading();   // "RELIANCE "
        " RELIANCE ".stripTrailing();  // " RELIANCE"

        // ═══ repeat(n) ═══
        "".repeat(5);     // ""
        "TCS ".repeat(3);  // "TCS TCS TCS "

        // ═══ lines() — Stream<String> ═══
        long lineCount = "Line1\nLine2\nLine3".lines().count();  // 3
        String firstLine = "A\nB\nC".lines().findFirst().orElse("");  // "A"

        // ═══ Optional.isEmpty() ═══
        Optional.of("X").isEmpty();     // false
        Optional.empty().isEmpty();     // true (cleaner than !isPresent())
    }

    public static void demonstrateFileMethods(Path dir) throws IOException {
        Path file = dir.resolve("test.txt");

        // ═══ Files.writeString — one-liner! ═══
        Files.writeString(file, "RELIANCE\nTCS\nHDFC");
        // Before Java 11: Files.write(file, "content".getBytes(), StandardOpenOption.CREATE);

        // ═══ Files.readString — one-liner! ═══
        String content = Files.readString(file);
        // Before Java 11: new String(Files.readAllBytes(file));

        // Combine with lines():
        long symbolCount = Files.readString(file).lines().count();  // 3
    }
}
