package com.bank.java11;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import java.io.IOException;
import java.nio.file.*;
import java.util.Optional;
import static org.assertj.core.api.Assertions.*;

class StringFileTest {

    @Test void isBlankVsIsEmpty() {
        assertThat("".isBlank()).isTrue();
        assertThat("   ".isBlank()).isTrue();
        assertThat("   ".isEmpty()).isFalse();  // NOT empty — has spaces!
        assertThat("TCS".isBlank()).isFalse();
    }

    @Test void stripHandlesUnicode() {
        String withUnicode = "\u00A0TCS\u00A0";  // non-breaking space
        assertThat(withUnicode.trim()).isEqualTo("\u00A0TCS\u00A0");  // trim FAILS!
        assertThat(withUnicode.strip()).isEqualTo("TCS");              // strip WORKS!
    }

    @Test void repeat() {
        assertThat("AB".repeat(3)).isEqualTo("ABABAB");
        assertThat("".repeat(0)).isEmpty();
    }

    @Test void lines() {
        assertThat("A\nB\nC".lines().toList()).containsExactly("A", "B", "C");
        assertThat("single".lines().toList()).containsExactly("single");
    }

    @Test void optionalIsEmpty() {
        assertThat(Optional.empty().isEmpty()).isTrue();
        assertThat(Optional.of("X").isEmpty()).isFalse();
    }

    @Test void filesReadWriteString(@TempDir Path dir) throws IOException {
        Path file = dir.resolve("test.txt");
        Files.writeString(file, "RELIANCE\nTCS");
        String content = Files.readString(file);
        assertThat(content).isEqualTo("RELIANCE\nTCS");
        assertThat(content.lines().count()).isEqualTo(2);
    }
}
