package com.bank.java8;

import org.junit.jupiter.api.Test;
import java.util.List;
import java.util.Optional;
import static org.assertj.core.api.Assertions.assertThat;

class FilesStringTest {

    @Test
    void stringAndOptionalConveniences() {
        String block = "SAV2001\n  \nCUR3001";

        List<String> ids = block.lines()
            .filter(s -> !s.isBlank())
            .map(String::strip)
            .toList();

        assertThat(ids).containsExactly("SAV2001", "CUR3001");
        assertThat("-".repeat(5)).isEqualTo("-----");
        assertThat(Optional.empty().isEmpty()).isTrue();   // Java 11 isEmpty
    }
}
